CREATE TABLE IF NOT EXISTS sales (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, doc_no VARCHAR(50) NOT NULL UNIQUE, txn_date DATE NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, counter_id BIGINT UNSIGNED NULL, issue_total DECIMAL(14,2) NOT NULL DEFAULT 0, cylinder_sale_total DECIMAL(14,2) NOT NULL DEFAULT 0, return_total DECIMAL(14,2) NOT NULL DEFAULT 0, net_amount DECIMAL(14,2) NOT NULL DEFAULT 0, received_amount DECIMAL(14,2) NOT NULL DEFAULT 0, balance_after DECIMAL(14,2) NOT NULL DEFAULT 0, status VARCHAR(10) NOT NULL DEFAULT 'POSTED', void_reason VARCHAR(500) NULL, voided_at DATETIME NULL, voided_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by BIGINT UNSIGNED NULL, INDEX idx_sales_date(txn_date), INDEX idx_sales_customer(customer_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;